/// <summary>
/// NDX_MultipleS_Quotation_Item
/// </summary>
class NDX_MultipleS_Quotation_Item extends NDX_MultipleSelect_Quotation
{
    InventTable          inventTable;
}

Method.Source:
protected void new(InventTable _inventTable, SalesQuotationTable _salesQuotationTable = null)
{
    NDXMultipleS_SalesQuotation   nDX_MultipleS_Quotation;
    ;
    super();

    inventTable = _inventTable;

    if(_salesQuotationTable)
    {
        salesQuotationTable = _salesQuotationTable;
        quotationId = salesQuotationTable.QuotationId;
    }

    itemValidityErrors.ValidityCheckType = NDXValidityCheckType::QuotationNumber;
    itemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValidityQuotationTest", quotationId);

    while select  nDX_MultipleS_Quotation
        where  nDX_MultipleS_Quotation.RefRecId_InventTable == inventTable.RecId
    {
        nDX_SelectionTmp.RefRecId_SalesQuotationTable = nDX_MultipleS_Quotation.RefRecId_SalesQuotationTable;
        nDX_SelectionTmp.doInsert();
    }
}

static public NDX_MultipleS_Quotation_Item construct(InventTable _inventTable, SalesQuotationTable _salesQuotationTable = null)
{
    return new NDX_MultipleS_Quotation_Item(_inventTable, _salesQuotationTable);
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "_obj">NDX_ItemValidity</param>
/// <param name = "_salesQouttionTable">SalesQuotationTable</param>
/// <returns>NDX_MultipleS_Quotation_Item object</returns>
static NDX_MultipleS_Quotation_Item new_FromNDX_ItemValidity(NDX_ItemValidity _obj, SalesQuotationTable _salesQouttionTable)
{
    NDX_MultipleS_Quotation_Item      nDX_MultipleS_Quotation_Item;
    ;
    nDX_MultipleS_Quotation_Item = new NDX_MultipleS_Quotation_Item(_obj.parmInventTable(), _salesQouttionTable);
    nDX_MultipleS_Quotation_Item.parmOItemValidity(_obj);
    return nDX_MultipleS_Quotation_Item;

}

/// <summary>
/// Checks if item is valid for a quotation
/// </summary>
/// <returns>container</returns>
public container isValid()
{
    NDXValidityMessage validityMessage = '';
    boolean     lIsValid = true;
    ;
    // keine Gültigkeitsprüfung hinterlegt
    if (nDX_SelectionTmp.RecId == 0)
    {
        return [lIsValid, validityMessage];
    }

    select firstonly nDX_SelectionTmp where nDX_SelectionTmp.RefRecId_SalesQuotationTable == salesQuotationTable.RecId;

    if (nDX_SelectionTmp)
    {
        return [lIsValid, validityMessage];
    }

    lIsValid        = false;

    // Der Artikel darf nur in den Angeboten [%1] angeboten werden!
    validityMessage = strFmtLB(strfmt("@NDX:NDXItemValidityQuotation", NDXMultipleS_SalesQuotation::Range2String(InventTable.RecId)));

    itemValidityErrors.ErrorMessage = validityMessage;
    oItemValidity.addErrorMessage(itemValidityErrors);

    return [lIsValid, validityMessage];
}

static void main(Args args = new Args())
{
    InventTable                     inventTable;
    NDX_MultipleS_Quotation_Item    multipleSelectClass;
    ;
    if (args.dataset() == tablenum(InventTable))
    {
        inventTable = args.record();
        multipleSelectClass = new NDX_MultipleS_Quotation_Item(inventTable);
        multipleSelectClass.openSelectForm();
    }
}
